import { toolsForService, testimonialsForService, workForService, serviceTasks, externalWebsiteUrl, processStepsForService, processWorkflows, experiencesForService, removeContentItem } from './content-model.js';
import { portfolioApi, backend, configureBackend } from './cloud-api.js';
const app = document.querySelector('#app');
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = (s, image=false) => { if(!s)return ''; try { const u=new URL(s,location.origin); return (['https:','http:'].includes(u.protocol) || (!image && u.protocol==='mailto:')) ? esc(u.href) : ''; } catch {return '';} };
const paths={ home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-8h6v8"/>',layers:'<path d="m12 3 10 6-10 6L2 9z"/><path d="m2 13 10 6 10-6M2 17l10 6 10-6"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18M10 12v3h4v-3"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4Z"/>',book:'<path d="M12 5C8 3 4 3 2 5v16c3-2 7-2 10 0 3-2 7-2 10 0V5c-2-2-6-2-10 0v16"/>',arrow:'<path d="M5 19 19 5M5 5h14v14"/>',right:'<path d="M4 12h16m-6-6 6 6-6 6"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',chart:'<path d="M4 3v18h18M8 16l4-5 4 2 5-7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6M17 2v6M3 11h18m-13 5h3"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="m2 5 10 8L22 5"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',coffee:'<path d="M3 8h14v7a6 6 0 0 1-6 6H9a6 6 0 0 1-6-6zM17 8h2a3 3 0 0 1 0 6h-2M6 2v3M10 2v3M14 2v3"/>',lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v3"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',check:'<path d="m4 12 5 5L20 6"/>'};
const icon = (name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.spark}</svg>`;
const nav=[['home','Home','home'],['portfolio','Portfolio','briefcase'],['services','Services','layers'],['projects','Projects','briefcase'],['about','About me','user'],['experience','My Experience','briefcase'],['tools','Tools & skills','bolt'],['testimonials','Testimonials','star'],['process','My Process','layers'],['blog','Blog','book'],['contact','FAQs & contact','chat']];
let content, adminContent, adminTab='profile', dirty=false, processServiceId='';
const api = portfolioApi;
function toast(message,error=false) { const el=$('#toast'); el.textContent=message; el.className=error?'show error':'show'; clearTimeout(toast.timer); toast.timer=setTimeout(()=>el.className='',4000); }
function route(){return location.hash.slice(1)||'home';}
function avatar(cls=''){const p=content.profile;return `<div class="avatar ${cls}">${p.photo?`<img src="${safeUrl(p.photo,true)}" alt="${esc(p.name)}">`:`<span>${esc(p.initials)}</span>`}</div>`;}
function externalUrl(value) { return esc(externalWebsiteUrl(value)); }
function socials(labeled=false) {
  const symbols={linkedin:'in',facebook:'f',instagram:'ig',youtube:'yt',tiktok:'tk',threads:'@',discord:'dc',whatsapp:'wa',telegram:'tg',x:'𝕏',twitter:'𝕏',pinterest:'p',github:'gh',behance:'be'};
  return content.socialLinks.filter(link=>externalUrl(link.url)).map(link=>`<a class="social ${labeled?'social-labeled':''}" href="${externalUrl(link.url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(link.label)}" title="${esc(link.label)}">${link.logo?`<img src="${safeUrl(link.logo,true)}" alt="">`:`<b>${esc(symbols[link.label.toLowerCase()]||link.label.slice(0,2))}</b>`}${labeled?`<span>${esc(link.label)}</span>`:''}</a>`).join('');
}
function toolLogo(tool,index=0) {
  return tool.logo?`<img class="tool-logo" src="${safeUrl(tool.logo,true)}" alt="${esc(tool.name)} logo" loading="lazy">`:`<i class="tool-symbol symbol-${index%3}">${esc(tool.name.slice(0,1))}</i>`;
}
function toolChips(tools) {
  return tools.map((tool,i)=>`<span class="associated-tool">${toolLogo(tool,i)}<span>${esc(tool.name)}</span></span>`).join('');
}
function shell(view){const p=content.profile;const r=route().split('/')[0];return `<div class="site-shell"><aside class="sidebar" id="sidebar"><a class="wordmark" href="#home">MA<span>®</span></a><div class="sidebar-profile">${avatar()}<h2>${esc(p.name)}</h2><p>${esc(p.role)}</p><div class="socials">${socials()}</div></div><span class="nav-label">YOUR NEXT CHAPTER</span><nav aria-label="Main navigation">${nav.map(([key,label,i])=>`<a href="#${key}" class="nav-item ${r===key?'active':''}" ${r===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${r===key?'<i class="active-dot"></i>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="coffee-note">${icon('coffee')}<span>Good things start<br>with a conversation.</span></div><p>© ${new Date().getFullYear()} ${esc(p.name)}<br><a class="manage-website-link" href="#admin">${icon('lock')} Manage website</a></p></div></aside><div class="main-wrap"><header class="topbar"><button class="mobile-menu icon-button" aria-label="Open navigation">${icon('menu')}</button><span class="breadcrumb">Portfolio <span>/</span> ${esc(nav.find(n=>n[0]===r)?.[1]||'Journal')}</span><a class="button button-small" href="#contact">Let’s work together ${icon('arrow')}</a></header><main id="main-content" tabindex="-1">${view}</main><footer class="site-footer"><span>${esc(p.footer)}</span><span>Made with intention. ${icon('coffee')}</span></footer></div></div>`;}
function cardHead(label,i,link,text='Explore'){return `<div class="card-heading"><h2><span class="icon-tile">${icon(i)}</span>${label}</h2>${link?`<a class="text-link" href="#${link}">${text} ${icon('arrow')}</a>`:''}</div>`;}
function serviceCard(service,index){return `<a class="service-card" href="#services/${encodeURIComponent(service.id)}" aria-label="View ${esc(service.title)} service details"><div class="service-top"><span class="icon-tile">${icon(service.icon)}</span><span class="card-number">${String(index+1).padStart(2,'0')}</span></div><h3>${esc(service.title)}</h3><p>${esc(service.description)}</p><span class="service-category">${esc(service.category)}</span><span class="service-open-label">View service details ${icon('right')}</span></a>`;}
function projectCard(p){return `<article class="project-card">${p.image?`<img src="${safeUrl(p.image,true)}" alt="${esc(p.title)}" loading="lazy">`:`<div class="project-art">${icon('layers')}</div>`}<div><span class="eyebrow">${esc(p.category)}</span><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p>${externalUrl(p.url)?`<a class="text-link" href="${externalUrl(p.url)}" target="_blank" rel="noopener noreferrer">View project ${icon('arrow')}</a>`:''}${relatedExperienceLinks('projectIds',p.id)}</div></article>`;}
function empty(title,text,i='briefcase'){return `<div class="empty-state"><span class="empty-icon">${icon(i)}</span><h3>${title}</h3><p>${text}</p></div>`;}
function postCard(p){return `<a class="post-card" href="#blog/${encodeURIComponent(p.id)}">${p.cover?`<img src="${safeUrl(p.cover,true)}" alt="${esc(p.title)}" loading="lazy">`:`<div class="post-art">${icon('book')}<span>THE JOURNAL</span></div>`}<div class="post-card-body"><span class="eyebrow">${esc(formatDate(p.date))}</span><h3>${esc(p.title)}</h3><p>${esc(p.excerpt)}</p><span class="text-link">Read story ${icon('arrow')}</span></div></a>`;}
function formatDate(s){const date=new Date(s+'T12:00:00');return isNaN(date)?'':date.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});}
function home(){const p=content.profile;return `<section class="hero"><div class="hero-copy"><div class="availability"><span></span>ONE PARTNER. SO MANY POSSIBILITIES.</div><p class="hero-question">${esc(p.eyebrow)}</p><h1>${esc(p.headline)} <span class="hero-coffee">☕</span></h1><p class="hero-intro">${esc(p.intro)}</p><div class="hero-actions"><a href="#contact" class="button">Let’s work together ${icon('arrow')}</a><a href="#services" class="secondary-link">Explore services ${icon('right')}</a></div></div><div class="hero-visual"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="visual-label label-top">A LITTLE STRATEGY.</span><div class="floating-tag tag-one">${icon('bolt')} A smarter workflow</div><div class="portrait-frame">${avatar('hero-avatar')}<div class="portrait-caption"><b>${esc(p.name)}</b><span>Your next right-hand person.</span></div></div><div class="floating-tag tag-two">${icon('check')} Consider it handled.</div><span class="visual-label label-bottom">A LOT OF GETTING IT DONE.</span><div class="orbit-dot"></div></div></section><section class="tools-strip"><div><span class="eyebrow">THE EVERYDAY ESSENTIALS</span><h2>Tools I work with</h2></div><div class="tool-chips">${content.tools.slice(0,6).map((tool,i)=>`<span>${toolLogo(tool,i)}${esc(tool.name)}</span>`).join('')}</div></section><div class="home-grid"><section class="panel services-panel">${cardHead('A few ways I can help','layers','services','All services')}<p class="section-subtitle">Big ideas. Small details. Everything in between.</p><div class="service-grid">${content.services.filter(s=>s.featured).slice(0,6).map(serviceCard).join('')}</div></section><section class="panel about-panel">${cardHead('The person behind it all','user','about','Meet me')}<div class="about-mini-art"><span class="decor-star">✳</span>${avatar('about-avatar')}<span class="handwritten">Hello, I’m ${esc(p.name.split(' ')[0])}.</span></div><h3>Many hats.<br>One dedicated partner.</h3><p>${esc(p.about.split('\n')[0])}</p><a class="text-link" href="#about">A little more about me ${icon('arrow')}</a></section><section class="panel projects-panel">${cardHead('Selected work','briefcase','projects','View projects')}${content.projects.length?`<div class="project-grid">${content.projects.slice(0,2).map(projectCard).join('')}</div>`:`<div class="work-placeholder"><div class="mini-browser"><div class="browser-bar"><i></i><i></i><i></i></div><div class="mini-browser-content"><span>Ideas into<br><b>action.</b></span><div class="mini-blocks"><i></i><i></i><i></i></div></div></div><div><span class="eyebrow">THE WORK SPEAKS</span><h3>A space for the<br>things we build.</h3><p>Project highlights are on their way.<br>Have something in mind? Let’s talk.</p><a class="text-link" href="#contact">Start a conversation ${icon('arrow')}</a></div></div>`}</section><section class="panel journal-panel">${cardHead('Notes & ideas','book','blog','The blog')}${content.posts.length?postCard(content.posts[0]):`<div class="journal-empty"><span class="journal-scribble">a fresh<br>perspective.</span><p>Thoughts on work, growth, and making business a little simpler.</p><a class="text-link" href="#blog">Visit the journal ${icon('arrow')}</a></div>`}</section>${content.testimonials.length?`<section class="panel testimonials-panel">${cardHead('Kind words','star','testimonials')}<blockquote>“${esc(content.testimonials[0].quote)}”</blockquote><b>${esc(content.testimonials[0].name)}</b><p>${esc(content.testimonials[0].role)}</p></section>`:''}${processSummary()}</div>${cta()}`;}
function cta(){return `<section class="cta-banner"><div><span class="eyebrow">LET’S MAKE ROOM FOR WHAT MATTERS</span><h2>${esc(content.profile.contactHeading)}</h2><p>${esc(content.profile.contactText)}</p></div><a class="button button-light" href="#contact">Let’s talk ${icon('arrow')}</a></section>`;}
function pageIntro(k,title,text){return `<div class="page-intro"><span class="eyebrow">${k}</span><h1>${title}</h1><p>${text}</p></div>`;}
function linkedPortfolio(serviceId) {
  const items=workForService(content,'portfolio',serviceId);
  return items.length?`<div class="service-portfolio-links"><span class="eyebrow">PORTFOLIO FOR THIS SERVICE</span>${items.map(item=>`<div class="service-portfolio-link"><span>${esc(item.title)}</span>${externalUrl(item.url)?`<a class="text-link" href="${externalUrl(item.url)}" target="_blank" rel="noopener noreferrer">Visit site ${icon('arrow')}</a>`:`<a class="text-link" href="#services/${encodeURIComponent(serviceId)}">View sample ${icon('right')}</a>`}</div>`).join('')}</div>`:'';
}
function servicesOverview(){const cats=['All',...new Set(content.services.map(service=>service.category))];return `${pageIntro('WHAT I CAN DO FOR YOU','Your goals. My many hats.','Tap a service to explore its tasks, tools, client feedback, and related work.')}<div class="filter-tabs" role="group" aria-label="Filter services">${cats.map((category,i)=>`<button class="filter ${i===0?'selected':''}" data-filter="${esc(category)}" aria-pressed="${i===0}">${esc(category)}</button>`).join('')}</div><div class="full-services">${content.services.map((service,i)=>`<article class="service-detail" data-category="${esc(service.category)}">${serviceCard(service,i)}<div class="service-details"><span class="eyebrow">HOW I CAN HELP</span><ul>${serviceTasks(service).map(task=>`<li>${icon('check')}${esc(task)}</li>`).join('')}</ul>${toolsForService(content,service.id).length?`<div class="service-tools"><span class="eyebrow">TOOLS FOR THIS SERVICE</span><div class="associated-tools">${toolChips(toolsForService(content,service.id))}</div></div>`:''}${linkedPortfolio(service.id)}</div></article>`).join('')}</div>${cta()}`;}
function servicePage(service) {
  if(!service)return `${pageIntro('SERVICES','This service isn’t available.','It may have been removed. Explore the other ways I can help.')}<a class="button" href="#services">Back to all services ${icon('right')}</a>`;
  const tools=toolsForService(content,service.id),websites=workForService(content,'portfolio',service.id),samples=workForService(content,'projects',service.id);
  return `<a class="text-link service-back" href="#services">← All services</a>${pageIntro(esc(service.category),esc(service.title),esc(service.description))}${service.image?`<img class="service-cover" src="${safeUrl(service.image,true)}" alt="${esc(service.title)}">`:''}<div class="service-page-grid"><section class="panel service-page-info">${cardHead('How I can help','spark')}<div class="service-page-text">${esc(service.overview||service.description)}</div><h3 class="service-section-subheading">Tasks & support</h3><ul class="service-task-list">${serviceTasks(service).map(task=>`<li>${icon('check')}${esc(task)}</li>`).join('')}</ul></section><aside class="panel service-page-toolkit">${cardHead('Tools for this service','bolt')}${tools.length?`<div class="associated-tools">${toolChips(tools)}</div>`:'<p class="section-subtitle">Tools for this service will appear here when added.</p>'}${linkedPortfolio(service.id)}</aside></div>${service.blocks.length?`<section class="panel service-extra-content">${service.blocks.map(serviceContentBlock).join('')}</section>`:''}<section class="panel service-work-section">${cardHead('Portfolio websites','layers')}${websites.length?`<div class="project-grid portfolio-grid">${websites.map(portfolioCard).join('')}</div>`:empty('Website samples are coming soon.','Related portfolio websites will appear here when added.','layers')}</section><section class="panel service-work-section">${cardHead('Samples & projects','briefcase')}${samples.length?`<div class="project-grid">${samples.map(projectCard).join('')}</div>`:empty('A space for related work.','Project samples for this service will appear here when added.','briefcase')}</section><section class="panel service-work-section">${cardHead('Testimonials for this service','star')}${testimonialResults(service.id)}</section>${processStepsForService(content,service.id).length?`<section class="panel service-work-section">${cardHead('My process for this service','target')}${processResults(service.id)}</section>`:''}${experiencesForService(content,service.id).length?`<section class="panel service-work-section">${cardHead('Experience with this service','briefcase')}<div class="experience-grid">${experiencesForService(content,service.id).map(item=>experienceCard(item)).join('')}</div></section>`:''}<a class="text-link service-back" href="#services">Explore all services ${icon('right')}</a>${cta()}`;
}
function serviceContentBlock(block) {
  const heading=block.title?`<h3>${esc(block.title)}</h3>`:'';
  if(block.type==='image')return `<div class="service-content-block">${heading}${block.image?`<figure><img src="${safeUrl(block.image,true)}" alt="${esc(block.caption||block.title)}" loading="lazy">${block.caption?`<figcaption>${esc(block.caption)}</figcaption>`:''}</figure>`:''}</div>`;
  if(block.type==='link')return `<div class="service-content-block service-link-block">${heading}${block.text?`<p class="service-page-text">${esc(block.text)}</p>`:''}${externalUrl(block.url)?`<a class="button button-secondary" href="${externalUrl(block.url)}" target="_blank" rel="noopener noreferrer">Visit website ${icon('arrow')}</a>`:''}</div>`;
  return `<div class="service-content-block">${heading}<div class="service-page-text">${esc(block.text)}</div></div>`;
}
function services(){const raw=route().split('/')[1];if(!raw)return servicesOverview();let id;try{id=decodeURIComponent(raw);}catch{return servicePage(null);}return servicePage(content.services.find(service=>service.id===id));}
function projects(){return `${pageIntro('A LOOK AT THE WORK','Ideas, brought to life.','Campaigns, systems, designs, and the work behind them.')}<section class="panel">${content.projects.length?`<div class="project-grid">${content.projects.map(projectCard).join('')}</div>`:empty('The next chapter is taking shape.','Real project highlights will appear here as they are added. In the meantime, let’s discuss what we could build together.')}</section>${cta()}`;}
function aboutGallery(position) {
  const photos=content.aboutPhotos.filter(photo=>photo.placement===position&&photo.image);
  if(!photos.length)return '';
  return `<div class="about-gallery gallery-${position}">${photos.map(photo=>`<figure class="about-photo"><img class="focus-${esc(['center','top','bottom','left','right'].includes(photo.focus)?photo.focus:'center')}" src="${safeUrl(photo.image,true)}" alt="${esc(photo.caption||content.profile.name)}" loading="lazy">${photo.caption?`<figcaption>${esc(photo.caption)}</figcaption>`:''}</figure>`).join('')}</div>`;
}
function about(){
  const p=content.profile,custom=content.aboutPhotos.some(photo=>photo.image);
  const left=aboutGallery('left')||(!custom?`<div class="about-portrait gallery-left">${avatar('about-large')}<span class="eyebrow">MANY SKILLS. ONE PERSON.</span></div>`:'');
  const right=aboutGallery('right'),above=aboutGallery('above'),below=aboutGallery('below');
  const layout=left&&right?'both':left?'left':right?'right':'single';
  return `${pageIntro('NICE TO MEET YOU',`Hello, I’m ${esc(p.name)}.`,esc(p.role))}<section class="panel about-layout layout-${layout} ${above?'has-above':''} ${below?'has-below':''}">${above}${left}<div class="about-bio"><h2>A partner for your<br>everyday & your next big thing.</h2>${p.about.split('\n').filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('')}${p.location?`<p class="location">Based in ${esc(p.location)}</p>`:''}<a class="button" href="#contact">Let’s connect ${icon('arrow')}</a></div>${right}${below}</section>${cta()}`;
}
function toolCard(tool,i) {
  return `<article class="panel tool-card">${toolLogo(tool,i)}<div><h3>${esc(tool.name)}</h3>${tool.description?`<p>${esc(tool.description)}</p>`:''}${externalUrl(tool.url)?`<a class="text-link" href="${externalUrl(tool.url)}" target="_blank" rel="noopener noreferrer">Visit tool ${icon('arrow')}</a>`:''}${relatedExperienceLinks('toolIds',tool.id)}</div></article>`;
}
function tools(){
  return `${pageIntro('MY DIGITAL TOOLKIT','Good tools. Better possibilities.','Explore my complete toolkit, then see the tools I use for each role and specialty.')}<section class="tool-section"><div class="tool-section-heading"><div><span class="eyebrow">THE COMPLETE TOOLKIT</span><h2>All my tools</h2></div><span class="tool-count">${content.tools.length} tools</span></div><div class="tool-grid">${content.tools.map(toolCard).join('')}</div></section>${content.toolGroups.map(group=>{
    const selected=content.tools.filter(tool=>group.toolIds.includes(tool.id));
    const services=content.services.filter(service=>group.serviceIds.includes(service.id));
    return `<section class="tool-section role-tools"><div class="tool-section-heading"><div><span class="eyebrow">BY ROLE & SPECIALTY</span><h2>${esc(group.title)}</h2></div><span class="tool-count">${selected.length} tools</span></div>${services.length?`<div class="group-services">${services.map(service=>`<span>${esc(service.title)}</span>`).join('')}</div>`:''}<div class="tool-grid">${selected.map(toolCard).join('')}</div>${!selected.length?'<p class="section-subtitle">Tools for this specialty are coming soon.</p>':''}</section>`;
  }).join('')}<section class="panel skills-panel">${cardHead('Skills that connect the dots','spark')}<div class="skill-cloud">${content.services.map(service=>`<span>${esc(service.title)}</span>`).join('')}</div></section>${cta()}`;
}
function portfolioCard(item){return `<article class="project-card portfolio-card">${item.image?`<img src="${safeUrl(item.image,true)}" alt="${esc(item.title)}" loading="lazy">`:`<div class="project-art">${icon('layers')}</div>`}<div><span class="eyebrow">${esc(item.category)}</span><h3 class="portfolio-title">${esc(item.title)}</h3><p>${esc(item.description)}</p>${externalUrl(item.url)?`<a class="button visit-site" href="${externalUrl(item.url)}" target="_blank" rel="noopener noreferrer">Visit site ${icon('arrow')}</a>`:''}${relatedExperienceLinks('portfolioIds',item.id)}</div></article>`;}
function portfolio(){return `${pageIntro('WEBSITES & DIGITAL EXPERIENCES','My portfolio.','A closer look at the websites and digital work I’ve built.')}<section class="panel">${content.portfolio.length?`<div class="project-grid portfolio-grid">${content.portfolio.map(portfolioCard).join('')}</div>`:empty('A space for the websites I create.','Website showcases will appear here as they’re added.','layers')}</section>${cta()}`;}
function processSummary(){const workflow=processWorkflows(content)[0];return workflow?`<section class="panel process-home-panel">${cardHead(esc(content.process.heading),'layers','process','See the process')}${workflow.serviceId?`<p class="section-subtitle">${esc(workflow.heading||content.services.find(service=>service.id===workflow.serviceId)?.title)}</p>`:''}<div class="process-preview">${workflow.steps.slice(0,4).map((step,i)=>`<div><span class="process-number">${String(i+1).padStart(2,'0')}</span><h3>${esc(step.title)}</h3><p>${esc(step.description)}</p></div>`).join('')}</div></section>`:'';}
function serviceTags(ids,data=content,cls='experience-service-tags') {
  const services=data.services.filter(service=>ids.includes(service.id));
  return services.length?`<div class="${cls}">${services.map(service=>`<a href="#services/${encodeURIComponent(service.id)}">${esc(service.title)}</a>`).join('')}</div>`:'';
}
function relatedExperienceLinks(field,id,data=content) {
  const rows=data.experiences.filter(item=>item[field].includes(id));
  return rows.length?`<div class="related-experience-links"><span>Related experience</span>${rows.map(item=>`<a href="#experience/${encodeURIComponent(item.id)}">${esc(item.name)}</a>`).join('')}</div>`:'';
}
function processStepCard(step,index,data=content) {
  return `<article class="process-step"><div class="process-step-top"><span class="process-number">${String(index+1).padStart(2,'0')}</span><span class="icon-tile">${icon(step.icon)}</span></div><h3>${esc(step.title)}</h3><p>${esc(step.description)}</p>${relatedExperienceLinks('processStepIds',step.id,data)}</article>`;
}
function processWorkflowCard(workflow,data=content) {
  const service=data.services.find(item=>item.id===workflow.serviceId),heading=workflow.heading||(service?service.title+' process':'General process');
  return `<section class="process-workflow" data-process-service="${esc(workflow.serviceId)}"><div class="process-workflow-heading"><h2>${esc(heading)}</h2>${service?`<a class="text-link" href="#services/${encodeURIComponent(service.id)}">${esc(service.title)} ${icon('right')}</a>`:''}</div>${workflow.intro?`<p class="process-workflow-intro">${esc(workflow.intro)}</p>`:''}<div class="process-timeline" aria-label="${esc(heading)} steps">${workflow.steps.map((step,i)=>processStepCard(step,i,data)).join('')}</div></section>`;
}
function processResults(serviceId='',query='',data=content) {
  const workflows=processWorkflows(data,serviceId,query);
  return workflows.length?workflows.map(workflow=>processWorkflowCard(workflow,data)).join(''):empty('No matching process yet.','Choose All services or try a different search. You can also get in touch to discuss how we could work together.','chat');
}
function processCount(serviceId='',query='',data=content) {
  const workflows=processWorkflows(data,serviceId,query),count=workflows.reduce((total,workflow)=>total+workflow.steps.length,0);
  return `${workflows.length} process${workflows.length===1?'':'es'} · ${count} step${count===1?'':'s'}${serviceId?' for '+(data.services.find(service=>service.id===serviceId)?.title||'this service'):''}${query.trim()?' matching your search':''}`;
}
function contentFilters(prefix,label,placeholder,data=content) {
  return `<div class="content-filters"><label class="field" for="${prefix}-search"><span>${esc(label)}</span><input id="${prefix}-search" type="search" placeholder="${esc(placeholder)}" autocomplete="off"></label><label class="field" for="${prefix}-service-filter"><span>${prefix==='process'?'My process for':'Experience in'}</span><select id="${prefix}-service-filter"><option value="">All services</option>${data.services.map(service=>`<option value="${esc(service.id)}">${esc(service.title)}</option>`).join('')}</select></label></div>`;
}
function processPage(){return `${pageIntro('HOW WE WORK TOGETHER',esc(content.process.heading),esc(content.process.intro))}${contentFilters('process','Search my process','Search steps or services…')}<div class="process-results" id="process-results"><p class="collection-result-count" data-result-status role="status" aria-live="polite">${esc(processCount())}</p><div data-result-content>${processResults()}</div></div>${cta()}`;}
function bindProcessFilter(root=document,data=content) {
  const search=root.querySelector('#process-search'),select=root.querySelector('#process-service-filter'),results=root.querySelector('#process-results');
  if(!search||!select||!results)return;
  const update=()=>{results.querySelector('[data-result-status]').textContent=processCount(select.value,search.value,data);results.querySelector('[data-result-content]').innerHTML=processResults(select.value,search.value,data);};
  search.addEventListener('input',update);select.addEventListener('change',update);
}
function experienceCard(item,data=content) {
  return `<article class="panel experience-card"><div class="experience-card-head">${item.image?`<img class="experience-logo" src="${safeUrl(item.image,true)}" alt="${esc(item.name)}" loading="lazy">`:`<span class="experience-logo experience-placeholder">${icon(item.kind==='person'?'user':'briefcase')}</span>`}<div><span class="eyebrow experience-kind">${item.kind==='person'?'PERSON':'COMPANY'}</span><h2><a href="#experience/${encodeURIComponent(item.id)}">${esc(item.name)}</a></h2>${item.role?`<p class="experience-role">${esc(item.role)}</p>`:''}</div></div><div class="experience-meta">${[item.period,item.location].filter(Boolean).map(value=>`<span>${esc(value)}</span>`).join('')}</div>${item.description?`<p class="experience-description">${esc(item.description)}</p>`:''}${serviceTags(item.serviceIds,data)}<a class="text-link" href="#experience/${encodeURIComponent(item.id)}">View experience ${icon('right')}</a></article>`;
}
function experienceMatches(serviceId='',query='',data=content) {
  const term=query.trim().toLowerCase();
  return (serviceId?experiencesForService(data,serviceId):data.experiences).filter(item=>!term||[item.name,item.kind,item.role,item.period,item.location,item.description,item.highlights,...data.services.filter(service=>item.serviceIds.includes(service.id)).map(service=>service.title)].join(' ').toLowerCase().includes(term));
}
function experienceResults(serviceId='',query='',data=content) {
  const rows=experienceMatches(serviceId,query,data);
  return rows.length?`<div class="experience-grid">${rows.map(item=>experienceCard(item,data)).join('')}</div>`:empty(data.experiences.length?'No matching experience yet.':'People and companies I’ve worked with.',data.experiences.length?'Try another search or choose All services.':'Experience and collaborations will appear here as I add them.','briefcase');
}
function experienceCount(serviceId='',query='',data=content){const count=experienceMatches(serviceId,query,data).length;return `${count} experience entr${count===1?'y':'ies'}`;}
function experienceOverview(){return `${pageIntro('THE PEOPLE & COMPANIES BEHIND THE WORK','My Experience.','Explore the roles, collaborations, and work that connect my skills to real business needs.')}${contentFilters('experience','Search my experience','Search companies, people, roles…')}<div id="experience-results"><p class="collection-result-count" data-result-status role="status" aria-live="polite">${esc(experienceCount())}</p><div data-result-content>${experienceResults()}</div></div>${cta()}`;}
function bindExperienceFilter(root=document,data=content) {
  const search=root.querySelector('#experience-search'),select=root.querySelector('#experience-service-filter'),results=root.querySelector('#experience-results');
  if(!search||!select||!results)return;
  const update=()=>{results.querySelector('[data-result-status]').textContent=experienceCount(select.value,search.value,data);results.querySelector('[data-result-content]').innerHTML=experienceResults(select.value,search.value,data);};
  search.addEventListener('input',update);select.addEventListener('change',update);
}
function experiencePage(item) {
  if(!item)return `${pageIntro('MY EXPERIENCE','This experience isn’t available.','It may have been removed. Explore my other roles and collaborations.')}<a class="button" href="#experience">Back to My Experience</a>`;
  const selected=(collection,field)=>content[collection].filter(row=>item[field].includes(row.id));
  const services=selected('services','serviceIds'),websites=selected('portfolio','portfolioIds'),projects=selected('projects','projectIds'),tools=selected('tools','toolIds'),reviews=selected('testimonials','testimonialIds'),workflows=processWorkflows(content).filter(workflow=>workflow.steps.some(step=>item.processStepIds.includes(step.id))),posts=selected('posts','postIds').filter(post=>post.published);
  const section=(title,i,body)=>`<section class="panel experience-section">${cardHead(title,i)}${body}</section>`;
  return `<a class="text-link service-back" href="#experience">← My Experience</a>${pageIntro(item.kind==='person'?'PERSON I’VE WORKED WITH':'COMPANY I’VE WORKED WITH',esc(item.name),esc(item.role))}<section class="panel experience-detail-header">${item.image?`<img class="experience-photo" src="${safeUrl(item.image,true)}" alt="${esc(item.name)}">`:''}<div class="experience-details"><div class="experience-meta">${[item.period,item.location].filter(Boolean).map(value=>`<span>${esc(value)}</span>`).join('')}</div>${item.description?`<div class="service-page-text">${esc(item.description)}</div>`:''}${item.highlights?`<h2 class="service-section-subheading">Work & highlights</h2><div class="service-page-text">${esc(item.highlights)}</div>`:''}${externalUrl(item.url)?`<a class="button button-secondary" href="${externalUrl(item.url)}" target="_blank" rel="noopener noreferrer">Visit website ${icon('arrow')}</a>`:''}</div></section>${services.length?section('Services for this experience','layers',`<div class="service-grid">${services.map(service=>serviceCard(service,content.services.indexOf(service))).join('')}</div>`):''}${websites.length?section('Related portfolio websites','layers',`<div class="project-grid portfolio-grid">${websites.map(portfolioCard).join('')}</div>`):''}${projects.length?section('Related projects & samples','briefcase',`<div class="project-grid">${projects.map(projectCard).join('')}</div>`):''}${tools.length?section('Tools used','bolt',`<div class="tool-grid">${tools.map(toolCard).join('')}</div>`):''}${reviews.length?section('Related testimonials','star',`<div class="testimonial-grid">${reviews.map(review=>testimonialCard(review)).join('')}</div>`):''}${workflows.length?section('Related processes','target',workflows.map(workflow=>processWorkflowCard(workflow)).join('')):''}${posts.length?section('Related stories','book',`<div class="post-grid">${posts.map(postCard).join('')}</div>`):''}${item.links.some(link=>externalUrl(link.url))?section('More from this experience','arrow',`<div class="experience-custom-links">${item.links.filter(link=>externalUrl(link.url)).map(link=>`<a class="button button-secondary" href="${externalUrl(link.url)}" target="_blank" rel="noopener noreferrer">${esc(link.label||'Visit link')} ${icon('arrow')}</a>`).join('')}</div>`):''}${cta()}`;
}
function experience(){const raw=route().split('/')[1];if(!raw)return experienceOverview();let id;try{id=decodeURIComponent(raw);}catch{return experiencePage(null);}return experiencePage(content.experiences.find(item=>item.id===id));}
function testimonialCount(serviceId='',data=content){const rows=testimonialsForService(data,serviceId),service=data.services.find(item=>item.id===serviceId);return `${rows.length} testimonial${rows.length===1?'':'s'}${service?' for '+service.title:''}`;}
function testimonialCard(testimonial,data=content) {
  return `<article class="quote-card"><span class="quote-mark">“</span><blockquote>${esc(testimonial.quote)}</blockquote><div class="quote-author">${testimonial.image?`<img src="${safeUrl(testimonial.image,true)}" alt="${esc(testimonial.name)}">`:icon('user')}<div><b>${esc(testimonial.name)}</b><span>${esc(testimonial.role)}</span></div></div>${serviceTags(testimonial.serviceIds,data,'testimonial-service-tags')}${relatedExperienceLinks('testimonialIds',testimonial.id,data)}</article>`;
}
function testimonialResults(serviceId='',data=content) {
  const rows=testimonialsForService(data,serviceId),service=data.services.find(item=>item.id===serviceId);
  return rows.length?`<div class="testimonial-grid">${rows.map(testimonial=>testimonialCard(testimonial,data)).join('')}</div>`:service?empty('No testimonials for this service yet.',`Feedback for ${esc(service.title)} will appear here when added.`,'star'):empty('Client stories, coming soon.','This space is reserved for genuine feedback from the people I’ve worked with.','star');
}
function testimonials(){return `${pageIntro('FROM THE PEOPLE I WORK WITH','Good work. Kind words.','Choose a service to see feedback from those client collaborations.')}<div class="testimonial-filter"><label for="testimonial-service-filter">Testimonials for</label><select id="testimonial-service-filter"><option value="">All services</option>${content.services.map(service=>`<option value="${esc(service.id)}">${esc(service.title)}</option>`).join('')}</select></div><section class="panel" id="testimonial-results"><p class="testimonial-result-count" data-testimonial-status role="status" aria-live="polite">${esc(testimonialCount())}</p><div data-testimonial-content>${testimonialResults()}</div></section>${cta()}`;}
function bindTestimonialFilter(root=document,data=content) {
  const select=root.querySelector('#testimonial-service-filter'),results=root.querySelector('#testimonial-results');
  if(select&&results)select.addEventListener('change',()=>{results.querySelector('[data-testimonial-status]').textContent=testimonialCount(select.value,data);results.querySelector('[data-testimonial-content]').innerHTML=testimonialResults(select.value,data);});
}
function blog(currentRoute=route()){let id;try{id=decodeURIComponent(currentRoute.split('/')[1]||'');}catch{id='invalid';}if(id){const p=content.posts.find(p=>p.id===id);if(!p)return `${pageIntro('THE JOURNAL','This story isn’t available.','It may have been unpublished or removed.')}<a class="button" href="#blog">Back to the blog</a>`;return `<article class="article"><a class="text-link" href="#blog">← Back to the journal</a><div class="page-intro"><span class="eyebrow">${esc(formatDate(p.date))} · ${esc(content.profile.name)}</span><h1>${esc(p.title)}</h1><p>${esc(p.excerpt)}</p></div>${p.cover?`<img class="article-cover" src="${safeUrl(p.cover,true)}" alt="${esc(p.title)}">`:''}<div class="article-body">${p.blocks.map(b=>b.type==='image'?`<figure>${b.image?`<img src="${safeUrl(b.image,true)}" alt="${esc(b.caption)}">`:''}<figcaption>${esc(b.caption)}</figcaption></figure>`:`<div class="article-text">${esc(b.text)}</div>`).join('')}</div>${relatedExperienceLinks('postIds',p.id)}</article>`;}return `${pageIntro('THE JOURNAL','A fresh perspective.','Notes, ideas, and a little behind the scenes.')}<section class="${content.posts.length?'post-grid':'panel'}">${content.posts.length?content.posts.map(postCard).join(''):empty('Something good is brewing.','Articles, quick thoughts, and updates will appear here when published. Grab a coffee and check back soon.','coffee')}</section>`;}
function contact(){const p=content.profile;return `${pageIntro('LET’S START A CONVERSATION',esc(p.contactHeading),esc(p.contactText))}<div class="contact-grid"><section class="panel contact-card">${icon('mail')}<h2>A simple hello goes a long way.</h2><p>Tell me about your business, your goals, and where you could use support.</p>${p.email?`<a class="button" href="mailto:${esc(p.email.replace(/[\r\n]/g,''))}">Email me ${icon('arrow')}</a><span class="contact-email">${esc(p.email)}</span>`:'<p class="contact-pending">Contact details are being updated. Please check back shortly.</p>'}${safeUrl(p.bookingUrl)?`<a class="secondary-link" target="_blank" rel="noopener noreferrer" href="${safeUrl(p.bookingUrl)}">Book a conversation ${icon('calendar')}</a>`:''}<div class="socials">${socials(true)}</div></section><section class="panel faq-panel">${cardHead('A few things you might ask','chat')}<div class="faqs">${content.faqs.map(f=>`<details><summary>${esc(f.question)}${icon('plus')}</summary><p>${esc(f.answer)}</p></details>`).join('')}</div></section></div>`;}
function bindServiceFilters(root=document){root.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{root.querySelectorAll('[data-filter]').forEach(other=>{other.classList.toggle('selected',other===button);other.setAttribute('aria-pressed',other===button);});root.querySelectorAll('[data-category]').forEach(card=>card.hidden=button.dataset.filter!=='All'&&card.dataset.category!==button.dataset.filter);}));}
function bindPublic(){ $('.mobile-menu')?.addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('.mobile-menu').setAttribute('aria-expanded',open);$('.mobile-menu').setAttribute('aria-label',open?'Close navigation':'Open navigation');});bindServiceFilters();bindTestimonialFilter();bindProcessFilter();bindExperienceFilter();}
async function render(){if(route()==='admin')return renderAdmin(); const r=route().split('/')[0];const views={home,portfolio,services,projects,about,experience,tools,testimonials,process:processPage,blog,contact};app.innerHTML=shell((views[r]||home)());document.title=`${nav.find(n=>n[0]===r)?.[1]||'Home'} — ${content.profile.name}`;bindPublic();window.scrollTo(0,0);if(['services','experience'].includes(r)&&route().includes('/'))$('#main-content').focus({preventScroll:true});}
const adminTabs=[['profile','Website text'],['portfolio','Portfolio'],['images','Photos & contact'],['socialLinks','Social links'],['aboutPhotos','About photos'],['experiences','My Experience'],['services','Services'],['projects','Projects'],['tools','Tools'],['toolGroups','Tools by role'],['testimonials','Testimonials'],['process','My Process'],['posts','Blog'],['faqs','FAQs'],['account','Account']];
const field=(label,key,value,type='text')=>`<label class="field"><span>${esc(label)}</span>${type==='textarea'?`<textarea data-key="${key}" rows="4">${esc(value)}</textarea>`:`<input type="${type}" data-key="${key}" value="${esc(value)}">`}</label>`;
function imageField(label,key,value){return `<div class="field image-field"><span>${label}</span>${value?`<img class="image-preview" src="${safeUrl(value,true)}" alt="${label}">`:`<div class="image-placeholder">${icon('image')} No image yet</div>`}<div class="image-controls"><label class="button button-secondary button-small">Upload image<input type="file" data-upload="${key}" accept="image/png,image/jpeg,image/webp,image/gif" hidden></label>${value?`<button class="quiet-button" data-remove-image="${key}" type="button">Remove image</button>`:''}</div><small>PNG, JPG, WebP or GIF · up to 3 MB</small></div>`;}
async function renderAdmin(){await configureBackend();if(!adminContent){try{adminContent=await api('/api/admin/content');}catch{app.innerHTML=`<div class="login-page"><a href="#home" class="login-back">← Back to portfolio</a><form id="login" class="login-card"><div class="icon-tile">${icon('lock')}</div><span class="eyebrow">YOUR PRIVATE WORKSPACE</span><h1>Welcome back.</h1><p>A little space to make this website yours.</p>${backend.mode==='supabase'?'<label class="field"><span>Owner email</span><input name="email" type="email" autocomplete="username" required></label>':''}<label class="field"><span>Admin password</span><input name="password" type="password" autocomplete="current-password" required></label><button class="button" type="submit">Sign in ${icon('right')}</button><p id="login-error" role="alert"></p><small>${backend.mode==='supabase'?'Use the owner email and password you created in Supabase Authentication.':'First login? Your generated password is in the private .data/admin-password.txt file on the server.'}</small></form></div>`;$('#login').onsubmit=async e=>{e.preventDefault();try{await api('/api/login',{method:'POST',body:JSON.stringify({email:new FormData(e.target).get('email'),password:new FormData(e.target).get('password')})});await renderAdmin();}catch(err){$('#login-error').textContent=err.message;}};return;}}
app.innerHTML=`<div class="admin-shell"><aside class="admin-sidebar"><a class="wordmark" href="#home">MA<span> / STUDIO</span></a><p class="nav-label">MAKE IT YOURS</p><nav>${adminTabs.map(([k,l])=>`<button data-tab="${k}" class="nav-item ${adminTab===k?'active':''}">${esc(l)}</button>`).join('')}</nav><a class="text-link" href="#home">View website ${icon('arrow')}</a><button id="logout" class="quiet-button">Sign out</button></aside><main class="admin-main"><header class="admin-header"><div><span class="eyebrow">CONTENT STUDIO</span><h1>${esc(adminTabs.find(t=>t[0]===adminTab)[1])}</h1><p>Changes stay here until you save them.</p></div><div class="admin-actions"><button id="preview" class="button button-secondary">Preview</button><button id="save" class="button">Save changes ${icon('check')}</button></div></header><p class="editor-note">${adminTab==='posts'?'Save as a draft, then switch to Published when your story is ready.':'Your saved changes update the public website immediately.'} <span id="save-state">${dirty?'Unsaved changes':''}</span></p><div class="admin-content">${adminFields()}</div></main></div>`;bindAdmin();}
function adminFields(){const c=adminContent,p=c.profile;
if(adminTab==='process')return processEditor();
if(adminTab==='experiences')return experienceEditor();
if(['portfolio','socialLinks','aboutPhotos','tools','toolGroups'].includes(adminTab))return collectionEditor(adminTab);
if(adminTab==='profile')return `<section class="editor-panel"><h2>Your introduction</h2><div class="fields-grid">${field('Your name','profile.name',p.name)}${field('Short role / tagline','profile.role',p.role)}${field('Initials (shown without a photo)','profile.initials',p.initials)}${field('Location (optional)','profile.location',p.location)}</div>${field('Opening question','profile.eyebrow',p.eyebrow,'textarea')}${field('Main headline','profile.headline',p.headline)}${field('Short introduction','profile.intro',p.intro,'textarea')}${field('About you','profile.about',p.about,'textarea')}${field('Contact heading','profile.contactHeading',p.contactHeading)}${field('Contact invitation','profile.contactText',p.contactText,'textarea')}${field('Footer message','profile.footer',p.footer)}</section>`;
if(adminTab==='images')return `<section class="editor-panel"><h2>Your profile photo & ways to connect</h2>${imageField('Profile photo (sidebar and Home)','profile.photo',p.photo)}<div class="fields-grid">${field('Contact email','profile.email',p.email,'email')}${field('Booking link','profile.bookingUrl',p.bookingUrl,'url')}</div><p class="editor-note">Use <b>About photos</b> for different photos on your About page, and <b>Social links</b> to add any social platform.</p></section>`;
if(adminTab==='account')return `<form class="editor-panel" id="password-form"><h2>Change your password</h2><p>Use at least 12 characters. You’ll sign in again after changing it.</p><label class="field"><span>New password</span><input id="new-password" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><label class="field"><span>Confirm new password</span><input id="confirm-password" type="password" autocomplete="new-password" required></label><button class="button" type="submit">Update password</button></form>`;
let rows=c[adminTab];return `<div class="collection-toolbar"><span>${rows.length} ${adminTab==='posts'?'posts':adminTab}</span><button class="button button-secondary" id="add-item">${icon('plus')} Add ${adminTab==='posts'?'post':adminTab==='faqs'?'question':adminTab.slice(0,-1)}</button></div>${rows.map((row,i)=>{const key=`${adminTab}.${i}`;let fields='';if(adminTab==='services')fields=`${field('Service name',key+'.title',row.title)}${field('Category',key+'.category',row.category)}${field('Short description',key+'.description',row.description,'textarea')}${field('Tasks (one per line, or separated with ·)',key+'.details',row.details,'textarea')}<label class="checkbox"><input type="checkbox" data-key="${key}.featured" ${row.featured?'checked':''}> Feature on Home</label>${servicePageEditor(row,i)}`;if(adminTab==='projects')fields=`${field('Project title',key+'.title',row.title)}${field('Category',key+'.category',row.category)}${field('Your work and results',key+'.description',row.description,'textarea')}${imageField('Project image',key+'.image',row.image)}${field('Project link (optional)',key+'.url',row.url,'url')}${selectionList('Related services',key+'.serviceIds',row.serviceIds,c.services,'title')}`;if(adminTab==='testimonials')fields=`${field('Client name',key+'.name',row.name)}${field('Client role / company',key+'.role',row.role)}${field('Their feedback',key+'.quote',row.quote,'textarea')}${imageField('Client photo (optional)',key+'.image',row.image)}${selectionList('Testimonials for — choose services',key+'.serviceIds',row.serviceIds,c.services,'title')}<p class="editor-note">Choose one or more services. Reviews without a service appear under All services.</p>`;if(adminTab==='faqs')fields=`${field('Question',key+'.question',row.question)}${field('Answer',key+'.answer',row.answer,'textarea')}`;if(adminTab==='posts')fields=`${field('Post title',key+'.title',row.title)}<div class="fields-grid">${field('Date',key+'.date',row.date,'date')}<label class="field"><span>Status</span><select data-key="${key}.published"><option value="false" ${!row.published?'selected':''}>Draft — private</option><option value="true" ${row.published?'selected':''}>Published — visible to everyone</option></select></label></div>${field('Short preview',key+'.excerpt',row.excerpt,'textarea')}${imageField('Cover image',key+'.cover',row.cover)}<h3>Story blocks</h3><p class="editor-note">Mix text and pictures. Use the arrows to change their order.</p>${row.blocks.map((b,j)=>`<div class="block-editor"><div class="block-toolbar"><b>${b.type==='text'?'Text':'Picture'} ${j+1}</b><div><button class="quiet-button" data-move="${i},${j},-1" ${j===0?'disabled':''} aria-label="Move block up">↑</button><button class="quiet-button" data-move="${i},${j},1" ${j===row.blocks.length-1?'disabled':''} aria-label="Move block down">↓</button><button class="quiet-button danger" data-remove-block="${i},${j}">Remove</button></div></div>${b.type==='text'?field('Text',`${key}.blocks.${j}.text`,b.text,'textarea'):imageField('Picture',`${key}.blocks.${j}.image`,b.image)+field('Caption / image description',`${key}.blocks.${j}.caption`,b.caption)}</div>`).join('')}<div class="block-actions"><button class="button button-secondary" data-add-block="${i},text">${icon('plus')} Add text</button><button class="button button-secondary" data-add-block="${i},image">${icon('image')} Add picture</button></div>`;return `<section class="editor-panel"><div class="item-heading"><h2>${esc(row.title||row.name||row.question||'New item')}</h2><button class="quiet-button danger" data-delete="${i}">Delete</button></div>${fields}</section>`;}).join('')}${!rows.length?`<div class="editor-panel">${empty('A blank canvas.','Use the Add button above to create your first item.','plus')}</div>`:''}`;}
function setValue(key,value){const ks=key.split('.');const last=ks.pop();let o=adminContent;for(const k of ks)o=o[k];pendingUploads.get(o)?.delete(last);o[last]=value;markDirty();}
function markDirty(){dirty=true;if($('#save-state'))$('#save-state').textContent='Unsaved changes';}

const collectionLabels={portfolio:'website',socialLinks:'social link',aboutPhotos:'photo',tools:'tool',toolGroups:'specialty'};
function selectField(label,key,value,options) {
  return `<label class="field"><span>${esc(label)}</span><select data-key="${key}">${options.map(([id,name])=>`<option value="${esc(id)}" ${value===id?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`;
}
function selectionList(label,key,selected,rows,nameKey) {
  return `<fieldset class="selection-list"><legend>${esc(label)}</legend>${rows.length?rows.map(row=>`<label class="checkbox"><input type="checkbox" data-list="${key}" value="${esc(row.id)}" ${selected.includes(row.id)?'checked':''}>${esc(row[nameKey])}</label>`).join(''):'<p>Add items first, then select them here.</p>'}</fieldset>`;
}
function collectionEditor(tab) {
  const rows=adminContent[tab],label=collectionLabels[tab];
  const notes={portfolio:'Add a website, highlight its name, and link visitors directly to it.',socialLinks:'Add as many platforms as you need. Each link appears in your sidebar and contact section. Custom icons are optional.',aboutPhotos:'Add photos just for your About page. Choose their position around your biography and use the arrows to reorder photos. Your profile photo stays separate.',tools:'Build your complete tool list with custom logos. Then use Tools by role to group them by specialty.',toolGroups:'Create groups such as SMM Tools, Ads Tools, or Automation Tools. Pick tools and link the group to the matching services.'};
  return `<p class="collection-description">${notes[tab]}</p><div class="collection-toolbar"><span>${rows.length} ${tab==='toolGroups'?'specialties':tab==='aboutPhotos'?'photos':tab==='socialLinks'?'social links':tab==='portfolio'?'websites':'tools'}</span><button class="button button-secondary" id="add-item">${icon('plus')} Add ${label}</button></div>${rows.map((row,i)=>{
    const key=`${tab}.${i}`;let fields='';
    if(tab==='portfolio')fields=`${field('Website / portfolio name',key+'.title',row.title)}${field('Category',key+'.category',row.category)}${field('Description',key+'.description',row.description,'textarea')}${imageField('Website screenshot or cover',key+'.image',row.image)}${field('Visit site link',key+'.url',row.url,'url')}${selectionList('Related services',key+'.serviceIds',row.serviceIds,adminContent.services,'title')}`;
    if(tab==='socialLinks')fields=`${field('Platform name (e.g. TikTok, Instagram, LinkedIn)',key+'.label',row.label)}${field('Your profile link',key+'.url',row.url,'url')}${imageField('Custom social icon (optional)',key+'.logo',row.logo)}`;
    if(tab==='aboutPhotos')fields=`${imageField('About photo',key+'.image',row.image)}${field('Caption / photo description',key+'.caption',row.caption)}<div class="fields-grid">${selectField('Position around your biography',key+'.placement',row.placement,[['left','Left of my bio'],['right','Right of my bio'],['above','Above my bio'],['below','Below my bio']])}${selectField('Photo crop focus',key+'.focus',row.focus,[['center','Center'],['top','Top'],['bottom','Bottom'],['left','Left'],['right','Right']])}</div>`;
    if(tab==='tools')fields=`${field('Tool name',key+'.name',row.name)}${imageField('Custom tool logo',key+'.logo',row.logo)}${field('Description (optional)',key+'.description',row.description,'textarea')}${field('Tool website (optional)',key+'.url',row.url,'url')}`;
    if(tab==='toolGroups')fields=`${field('Specialty / role heading (e.g. SMM Tools)',key+'.title',row.title)}${selectionList('Choose tools from your full list',key+'.toolIds',row.toolIds,adminContent.tools,'name')}${selectionList('Show these tools on the matching services',key+'.serviceIds',row.serviceIds,adminContent.services,'title')}`;
    return `<section class="editor-panel collection-item"><div class="item-heading"><h2>${esc(row.title||row.name||row.label||row.caption||`Photo ${i+1}`)}</h2><div class="item-controls"><button class="quiet-button" data-move-item="${tab},${i},-1" ${i===0?'disabled':''} aria-label="Move ${label} earlier">↑</button><button class="quiet-button" data-move-item="${tab},${i},1" ${i===rows.length-1?'disabled':''} aria-label="Move ${label} later">↓</button><button class="quiet-button danger" data-delete="${i}">Delete</button></div></div>${fields}</section>`;
  }).join('')}${!rows.length?`<div class="editor-panel">${empty('Make this space your own.',`Use Add ${label} to get started.`,'plus')}</div>`:''}`;
}
function deleteCollectionItem(tab,index) {removeContentItem(adminContent,tab,index);}
function bindCollectionEditor() {
  document.querySelectorAll('[data-list]').forEach(el=>el.onchange=()=>{
    const ids=[...document.querySelectorAll('[data-list]')].filter(other=>other.dataset.list===el.dataset.list&&other.checked).map(other=>other.value);
    setValue(el.dataset.list,ids);
  });
  document.querySelectorAll('[data-move-item]').forEach(button=>button.onclick=()=>{
    const [tab,rawIndex,rawDirection]=button.dataset.moveItem.split(',');const index=Number(rawIndex),next=index+Number(rawDirection),rows=adminContent[tab];
    if(next<0||next>=rows.length)return;
    [rows[index],rows[next]]=[rows[next],rows[index]];markDirty();renderAdmin();
  });
}

